import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

from google.cloud import monitoring_v3


def query_recent_metric_datapoints(
    project_id: str,
    metric_type: str,
    minutes: int,
    resource_type: Optional[str] = None,
    metric_labels: Optional[Dict[str, str]] = None,
    resource_labels: Optional[Dict[str, str]] = None,
) -> List[Dict[str, Any]]:
    client = monitoring_v3.MetricServiceClient()

    end_time = datetime.now(timezone.utc)
    start_time = end_time - timedelta(minutes=minutes)

    filter_parts = [f'metric.type = "{metric_type}"']
    if resource_type:
        filter_parts.append(f'resource.type = "{resource_type}"')
    for key, value in (metric_labels or {}).items():
        filter_parts.append(f'metric.labels.{key} = "{value}"')
    for key, value in (resource_labels or {}).items():
        filter_parts.append(f'resource.labels.{key} = "{value}"')

    interval = monitoring_v3.TimeInterval(
        {
            "end_time": {"seconds": int(end_time.timestamp())},
            "start_time": {"seconds": int(start_time.timestamp())},
        }
    )

    results = client.list_time_series(
        request={
            "name": f"projects/{project_id}",
            "filter": " AND ".join(filter_parts),
            "interval": interval,
            "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
        }
    )

    datapoints: List[Dict[str, Any]] = []

    for series in results:
        series_metric_labels = dict(series.metric.labels)
        series_resource_labels = dict(series.resource.labels)

        for point in series.points:
            value = point.value
            typed_value: Any = None

            which = value.WhichOneof("value")
            if which == "double_value":
                typed_value = value.double_value
            elif which == "int64_value":
                typed_value = value.int64_value
            elif which == "bool_value":
                typed_value = value.bool_value
            elif which == "string_value":
                typed_value = value.string_value
            elif which == "distribution_value":
                typed_value = {
                    "count": value.distribution_value.count,
                    "mean": value.distribution_value.mean,
                    "sum_of_squared_deviation": value.distribution_value.sum_of_squared_deviation,
                }

            datapoints.append(
                {
                    "metric_type": series.metric.type,
                    "resource_type": series.resource.type,
                    "metric_labels": series_metric_labels,
                    "resource_labels": series_resource_labels,
                    "interval_start": point.interval.start_time.isoformat(),
                    "interval_end": point.interval.end_time.isoformat(),
                    "value": typed_value,
                }
            )

    return datapoints


def query_recent_metric_datapoints_from_env(
    metric_type: str,
    minutes: int,
    resource_type: Optional[str] = None,
    metric_labels: Optional[Dict[str, str]] = None,
    resource_labels: Optional[Dict[str, str]] = None,
) -> List[Dict[str, Any]]:
    project_id = os.environ["GOOGLE_CLOUD_PROJECT"]
    return query_recent_metric_datapoints(
        project_id=project_id,
        metric_type=metric_type,
        minutes=minutes,
        resource_type=resource_type,
        metric_labels=metric_labels,
        resource_labels=resource_labels,
    )
